const q = P.heat;
const s1 = 12;
const s2 = 26;
const s3 = 22;
const s4 = 60;
const s5 = 12;
const tempAt = (x) => {
  let h = x, T;
  if (h <= s1) T = -40 + (40 / s1) * h;
  else if (h <= s1 + s2) T = 0;
  else if (h <= s1 + s2 + s3) T = (100 / s3) * (h - s1 - s2);
  else if (h <= s1 + s2 + s3 + s4) T = 100;
  else T = 100 + (40 / s5) * (h - s1 - s2 - s3 - s4);
  return T;
};
